/**
 * Playthrough guides: the intended path through each mainline Pokémon game.
 *
 * Each guide is a "roadmap" not a step-by-step walkthrough: the milestones
 * in the order Nintendo intended, the story arc, practical tips, and
 * post-game. Written from game knowledge; links to full walkthroughs
 * live on the guide pages.
 */

export interface GuideMilestone {
  /** e.g. "Cortondo Gym" */
  name: string;
  /** e.g. "Bug · Katy · recommended Lv. 12–15" */
  detail: string;
  kind: "gym" | "trial" | "titan" | "base" | "story" | "elite" | "champion" | "other";
}

export interface GameGuide {
  slug: string;
  title: string;
  generation: string;
  /** True for spin-off games (Mystery Dungeon, Snap, Ranger, …) — the
   *  guides index lists these in their own section, not by generation. */
  spinoff?: boolean;
  tagline: string;
  path: GuideMilestone[];
  story: string[];
  tips: string[];
  postgame: string[];
}

